"""Sandboxed storage for files generated by the agent.

The agent never chooses a path. It supplies a file *name*, which is reduced to a safe basename
and written under engine/generated/<session_id>/. Existing files are never overwritten:
a numeric suffix is added instead. Copying into the user's workspace only happens through
add_to_workspace(), which the UI calls when the user clicks "Add to Workspace".
"""

from __future__ import annotations

import os
import re
import shutil
import threading
import uuid
from dataclasses import asdict, dataclass
from datetime import datetime, timezone

from ..paths import GENERATED_DIR as GENERATED_ROOT
MAX_ARTIFACT_BYTES = 200_000

# artifact_type -> allowed extensions
ARTIFACT_TYPES: dict[str, tuple[str, ...]] = {
    "python_strategy": (".py",),
    "ml_strategy": (".py",),
    "analysis_report": (".md", ".txt"),
    "experiment_plan": (".md", ".txt"),
    "data_report": (".json", ".csv"),
}

_SAFE_CHARS = re.compile(r"[^A-Za-z0-9._-]+")


class ArtifactError(ValueError):
    pass


@dataclass
class Artifact:
    id: str
    session_id: str
    filename: str
    type: str
    description: str
    path: str
    size_bytes: int
    created_utc: str

    def public(self) -> dict:
        return asdict(self)


def sanitize_filename(filename: str, artifact_type: str) -> str:
    if artifact_type not in ARTIFACT_TYPES:
        raise ArtifactError(f"artifact_type must be one of {sorted(ARTIFACT_TYPES)}")
    base = os.path.basename(str(filename).replace("\\", "/"))  # drop any directory part
    base = _SAFE_CHARS.sub("_", base).strip("._")
    if not base:
        raise ArtifactError("filename is empty after sanitizing")
    stem, ext = os.path.splitext(base)
    allowed = ARTIFACT_TYPES[artifact_type]
    if ext.lower() not in allowed:
        ext = allowed[0]
    stem = stem[:80] or "artifact"
    return f"{stem}{ext.lower()}"


def _unique_path(directory: str, filename: str) -> str:
    stem, ext = os.path.splitext(filename)
    candidate = os.path.join(directory, filename)
    n = 2
    while os.path.exists(candidate):
        candidate = os.path.join(directory, f"{stem}_{n}{ext}")
        n += 1
    return candidate


def _inside(path: str, root: str) -> bool:
    path, root = os.path.realpath(path), os.path.realpath(root)
    return os.path.commonpath([path, root]) == root


class ArtifactStore:
    def __init__(self, root: str = GENERATED_ROOT) -> None:
        self.root = root
        self._items: dict[str, Artifact] = {}
        self._lock = threading.Lock()

    def create(self, session_id: str, filename: str, content: str, artifact_type: str, description: str) -> Artifact:
        if not re.fullmatch(r"[A-Za-z0-9-]{1,64}", session_id):
            raise ArtifactError("invalid session id")
        data = content.encode("utf-8")
        if len(data) > MAX_ARTIFACT_BYTES:
            raise ArtifactError(f"artifact too large ({len(data)} bytes > {MAX_ARTIFACT_BYTES})")
        safe = sanitize_filename(filename, artifact_type)
        directory = os.path.join(self.root, session_id)
        os.makedirs(directory, exist_ok=True)
        with self._lock:
            path = _unique_path(directory, safe)
            if not _inside(path, self.root):
                raise ArtifactError("refusing to write outside the generated directory")
            with open(path, "xb") as fh:  # "x": fail rather than overwrite
                fh.write(data)
            art = Artifact(
                id=uuid.uuid4().hex[:12],
                session_id=session_id,
                filename=os.path.basename(path),
                type=artifact_type,
                description=description.strip()[:300],
                path=path,
                size_bytes=len(data),
                created_utc=datetime.now(timezone.utc).isoformat(timespec="seconds"),
            )
            self._items[art.id] = art
        return art

    def get(self, artifact_id: str) -> Artifact:
        art = self._items.get(artifact_id)
        if art is None or not os.path.isfile(art.path):
            raise KeyError(artifact_id)
        return art

    def read(self, artifact_id: str) -> str:
        with open(self.get(artifact_id).path, "r", encoding="utf-8") as fh:
            return fh.read()

    def for_session(self, session_id: str) -> list[Artifact]:
        return [a for a in self._items.values() if a.session_id == session_id and os.path.isfile(a.path)]

    def delete(self, artifact_id: str) -> None:
        art = self.get(artifact_id)
        if not _inside(art.path, self.root):
            raise ArtifactError("artifact path escaped the generated directory")
        os.remove(art.path)
        with self._lock:
            self._items.pop(artifact_id, None)

    def add_to_workspace(self, artifact_id: str, workspace_dir: str) -> str:
        """Explicit user action: copy into the workspace without overwriting anything."""
        art = self.get(artifact_id)
        if not workspace_dir or not os.path.isdir(workspace_dir):
            raise ArtifactError(f"workspace directory does not exist: {workspace_dir}")
        target = _unique_path(os.path.realpath(workspace_dir), art.filename)
        shutil.copyfile(art.path, target)
        return target
